mapper.select:
/* selectUserJoinCount - Lee JiSeob */
SELECT
COUNT(*) AS CNT
FROM (
SELECT D.USER_ID FROM SCA100 C /* 종사자 */ JOIN SAA200 D /* 사용자 */ ON D.ENFSN_NO = C.ENFSN_NO JOIN TMP_APRV_INST F /* 승인기관 (임시테이블) */ ON F.INST_NO = C.OGDP_INST_NO /* 소속기관번호 */
AND F.INST_NO IN ( SELECT INST_NO /* 기관번호 */ FROM SAA000 /** 통합기관 */ START WITH INST_NO = #{SRCH_UP_INST_NO} /* 검색할 상위기관번호 */ CONNECT BY PRIOR INST_NO = UP_INST_NO )
AND (F.INST_NO = #{APRV_INST_NO} OR F.UP_INST_NO = #{APRV_INST_NO} OR F.UP_APRV_INST_NO = #{APRV_INST_NO})
AND F.INST_NO = #{OGDP_INST_NO}
AND D.USER_ID LIKE '%' || #{SEARCH_VALUE} || '%'
AND C.FLNM_ENCPT = #{SEARCH_VALUE_ENCPT}
AND D.JOIN_APLY_DT >= TO_DATE(#{APPLY_START_DATE} || '000000', 'YYYYMMDDHH24MISS')
AND D.JOIN_APLY_DT <= TO_DATE(#{APPLY_END_DATE} || '235959', 'YYYYMMDDHH24MISS')
AND 1=1
AND 1=2
AND D.USER_ID_USE_SE_CD = #{USER_ID_USE_SE_CD}
AND F.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}
AND F.INST_TYPE_SE_CD = #{INST_TYPE_SE_CD}
AND F.INST_NM LIKE '%' || #{INST_NM} || '%'
) X

/* selectUserJoin - Lee JiSeob */
SELECT
X.USER_ID, C##RG.DEC_B64(X.USER_NM) AS USER_NM, X.USER_ID_USE_SE_CD, X.USER_ID_USE_SE_NM, X.USER_TYPE, X.USER_TYPE_NM, TO_CHAR(X.JOIN_APLY_DT, 'YYYY-MM-DD HH24:MI:SS') AS JOIN_APLY_DT, X.ENFSN_NO, X.UNT_TASKWK_SE_CD, X.INST_NM, X.INST_TYPE_SE_CD, X.INST_TYPE_SE_NM FROM (
SELECT D.USER_ID, C.FLNM_ENCPT AS USER_NM, D.USER_ID_USE_SE_CD, (SELECT G.CMMNS_CD_VALUE_NM FROM SAC100 G /* 공통코드 값 */ WHERE G.CMMNS_CD_ID = 'USER_ID_USE_SE_CD' AND G.CMMNS_CD_VALUE = D.USER_ID_USE_SE_CD) AS USER_ID_USE_SE_NM, 'WORKER' AS USER_TYPE, '종사자' AS USER_TYPE_NM, D.JOIN_APLY_DT, C.ENFSN_NO, F.UNT_TASKWK_SE_CD, F.INST_NM, F.INST_TYPE_SE_CD, CASE WHEN F.INST_TYPE_SE_CD IS NULL THEN '' ELSE ( SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'INST_TYPE_SE_CD' /* 공통코드아이디 */ AND CMMNS_CD_VALUE = F.INST_TYPE_SE_CD /* 기관유형구분코드 */ AND USE_YN = 'Y' /* 공통코드_사용여부 */ ) END AS INST_TYPE_SE_NM /* 기관유형구분명 */ FROM SCA100 C /* 종사자 */ JOIN SAA200 D /* 사용자 */ ON D.ENFSN_NO = C.ENFSN_NO JOIN TMP_APRV_INST F /* 승인기관 (임시테이블) */ ON F.INST_NO = C.OGDP_INST_NO /* 소속기관번호 */
AND F.INST_NO IN ( SELECT INST_NO /* 기관번호 */ FROM SAA000 /** 통합기관 */ START WITH INST_NO = #{SRCH_UP_INST_NO} /* 검색할 상위기관번호 */ CONNECT BY PRIOR INST_NO = UP_INST_NO )
AND (F.INST_NO = #{APRV_INST_NO} OR F.UP_INST_NO = #{APRV_INST_NO} OR F.UP_APRV_INST_NO = #{APRV_INST_NO})
AND F.INST_NO = #{OGDP_INST_NO}
AND D.USER_ID LIKE '%' || #{SEARCH_VALUE} || '%'
AND C.FLNM_ENCPT = C##RG.ENC_B64(#{SEARCH_VALUE})
AND D.JOIN_APLY_DT >= TO_DATE(#{APPLY_START_DATE} || '000000', 'YYYYMMDDHH24MISS')
AND D.JOIN_APLY_DT <= TO_DATE(#{APPLY_END_DATE} || '235959', 'YYYYMMDDHH24MISS')
AND 1=1
AND 1=2
AND D.USER_ID_USE_SE_CD = #{USER_ID_USE_SE_CD}
AND F.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}
AND F.INST_TYPE_SE_CD = #{INST_TYPE_SE_CD}
AND F.INST_NM LIKE #{INST_NM} || '%'
) X
ORDER BY X.JOIN_APLY_DT DESC, X.USER_ID ASC, X.USER_TYPE ASC
OFFSET #{OFFSET_IDX} ROWS FETCH NEXT #{ROW_COUNT} ROWS ONLY

mapper.update:
/* saveGiveBackUserJoin - Lee JiSeob */
UPDATE SAA200 /* 사용자 */
SET
JOIN_AUTZR_ID = #{JOIN_AUTZR_ID}, JOIN_APRV_YN = 'Y', JOIN_APRV_YMD = #{JOIN_APRV_YMD},
JOIN_RJCT_CS_CN = #{JOIN_RJCT_CS_CN}, DEL_CS_CN = #{DEL_CS_CN}, USE_STPGE_CS_CN = #{USE_STPGE_CS_CN},
LAST_MDFR_ID = #{LAST_MDFR_ID}, LAST_MDFCN_DT = SYSDATE,
USER_ID_USE_SE_CD = #{USER_ID_USE_SE_CD}
WHERE USER_ID = #{USER_ID}


/* saveUserJoin - Lee JiSeob */

UPDATE SAA200 /*  사용자 */

SET

    JOIN_AUTZR_ID = #{JOIN_AUTZR_ID},
    JOIN_APRV_YN = 'Y',
    JOIN_APRV_YMD = #{JOIN_APRV_YMD},
    LAST_MDFR_ID = #{LAST_MDFR_ID},
    LAST_MDFCN_DT = SYSDATE,

    USER_ID_USE_SE_CD = #{USER_ID_USE_SE_CD}

WHERE USER_ID = #{USER_ID}

